import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void cumprod_kernel(const scalar_t* __restrict__ input,
                               scalar_t* __restrict__ output,
                               int64_t outer,
                               int64_t inner) {
    // one thread per outer (batch) element
    int64_t idx = blockIdx.x;
    if (idx >= outer) return;

    const scalar_t* in_ptr  = input + idx * inner;
    scalar_t*       out_ptr = output + idx * inner;

    float prod = 1.0f;
    #pragma unroll
    for (int64_t i = 0; i < inner; ++i) {
        // convert half->float, multiply, convert back
        prod *= __half2float(in_ptr[i]);
        out_ptr[i] = __float2half(prod);
    }
}

// Dispatcher
torch::Tensor cumprod_forward_cuda(torch::Tensor input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "only fp16 (Half) tensors are supported");
    int64_t ndim = input.dim();
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");

    // we only support cumprod along the last dimension for simplicity
    TORCH_CHECK(dim == ndim - 1, "this kernel only supports dim == input.dim() - 1");

    auto sizes = input.sizes();
    int64_t inner = sizes[dim];
    int64_t outer = input.numel() / inner;

    auto output = torch::empty_like(input);

    const dim3 grid(outer);
    const dim3 block(1);

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "cumprod_kernel", ([&] {
        cumprod_kernel<scalar_t><<<grid, block>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            outer,
            inner);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel failed: ") + cudaGetErrorString(err));
    }
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("cumprod_forward", &cumprod_forward_cuda, "Cumulative product forward (CUDA)");
}
'''

# compile the extension
cumprod_ext = load_inline(name='cumprod_ext',
                          cpp_sources='',
                          cuda_sources=src,
                          functions=['cumprod_forward'],
                          verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    Supports only fp16 tensors and cumulative product along the last dimension.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ensure contiguous and correct dtype
        if not x.is_contiguous():
            x = x.contiguous()
        if x.dtype != torch.float16:
            raise TypeError("ModelNew only supports fp16 (torch.float16) tensors")
        return cumprod_ext.cumprod_forward(x, self.dim)

# Example usage (mirrors the reference script)
if __name__ == "__main__":
    batch_size = 32768
    input_shape = (32768,)
    dim = 1

    model = ModelNew(dim)
    inp = torch.rand(batch_size, *input_shape, device='cuda', dtype=torch.float16)
    out = model(inp)
    # sanity check against torch.cumprod
    ref = torch.cumprod(inp, dim=dim)
    assert torch.allclose(out, ref, atol=1e-3, rtol=1e-3)
